GROUPS.all = [...new Set([...all.filter((n) => !/^astra-/.test(n)), ...GROUPS.astra, ...GROUPS.unit])];
// (round 105, units105) what a release runs: the default app list (qa, what a run with no names runs) and every unit
// test. Round 104 ran the whole unit list for the first time in a while and found four failing on the base for weeks
// (they were never in a usual release run). Timing tests in it are load-aware (dev/loadwait.js): a box too busy to
// tell says "can't tell" on its line instead of failing. docs/upgrades/units105.md
// (round 114, owner: "our testing list is too long") the release runs what the app's core needs: chats, projects, sync,
// the Lab, speed. (round 116, slim116) the Life side (Paris, quests, outings) and the music studio are gone from the app,
// and their checks with them, so the "extra" group they had moved to is gone too: a release is the qa group + every unit test.
// (round 123, checksweep123) the app checks of what the app is now (chats in projects, the engines, access, data safety,
// sync, the Lab's start, the first run). Since round 116 three app checks broke unseen (makes, smooth46, access-chat) and
// a sweep found more, all outside the release: these run at every release now. Each passed in the sweep's last run;
// 20 checks, ≈ 20 min on the 4-core box (docs/upgrades/checksweep123.md)
GROUPS.core = ['access-chat', 'access-astra', 'aicheck', 'collab-appserver', 'datasafe', 'crashsafe', 'chatcore', 'chat-new-row', 'chatsafe55', 'connections', 'appsearch', 'firstrun', 'calmstart', 'labboot', 'keptaside94', 'guardloss78', 'devices90', 'projects', 'sync', 'makes'];
GROUPS.release = [...new Set([...GROUPS.qa, ...GROUPS.unit, ...GROUPS.core])]; // (round 123) + core

if (argv.includes('--list')) {
  for (const [g, list] of Object.entries(GROUPS)) if (g !== 'all') console.log(`${g}: ${list.join(' ')}`);
  console.log(`all: every check above (${GROUPS.all.length})`);
  process.exit(0);
}
// (round 44) --names <group…>: the checks one per line (to split "all" into parts that fit a time limit)
if (argv.includes('--names')) { console.log([...new Set((names.length ? names : ['qa']).flatMap((n) => GROUPS[n] || [n]))].join('\n')); process.exit(0); } // run them with --exact
// (round 44) --exact: the names are checks, never groups ("a11y" is both: a part of "all" ran its whole group again)
const wanted = [...new Set((names.length ? names : ['qa']).flatMap((n) => (!argv.includes('--exact') && GROUPS[n]) || [UNIT.includes(n) ? `unit:${n}` : n]))];
for (const n of wanted) if (!n.startsWith('unit:') && !all.includes(n)) { console.error(`No check "${n}" (sh dev/run-checks.sh --list)`); process.exit(2); }

// (round 106, tmpclean106) one run folder (<tmp>/hearth-run-XXXXXX), a temp root per check in it (TMPDIR & co.), removed
// when the check ends, and the guard: /tmp/hearth-* folders a check left are named at the end (dev/tmp-guard.js)
const TG = require('./tmp-guard.js').create();
// ---------- fixtures (made once, reused; all in the temp folder, never in the app) ----------
const T = '/tmp'; // the checks name these paths themselves
const sh = (cmd, a) => execFileSync(cmd, a, { cwd: ROOT, stdio: ['ignore', 'ignore', 'inherit'], env: { ...process.env, TMPDIR: TG.runDir } }); // (tmpclean106) a maker's scratch goes with the run folder
